import DashboardLayout, { type DashboardNavItem } from "@/components/DashboardLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useAuth } from "@/hooks/useAuth";
import { buildReportPresentation } from "@/lib/reportPresentation";
import { trpc } from "@/lib/trpc";
import { zodResolver } from "@hookform/resolvers/zod";
import { AlertTriangle, Banknote, Bell, BriefcaseBusiness, CheckCircle2, CircleDollarSign, ClipboardCheck, FileWarning, FolderKanban, LayoutDashboard, Plus, ShieldCheck, Smartphone, TestTube2, UsersRound, WalletCards } from "lucide-react";
import React, { useEffect, useRef, useState } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import { useLocation, useSearch } from "wouter";
import { z } from "zod";

const reportSchema = z.object({
  testCycleId: z.string().uuid("اختر دورة اختبار"),
  deviceId: z.string().uuid("اختر جهازاً"),
  title: z.string().min(5, "اكتب عنواناً أوضح"),
  category: z.enum(["functional", "ui", "performance", "crash"]),
  severity: z.enum(["critical", "major", "minor"]),
  stepsToReproduce: z.string().min(10, "أضف خطوات واضحة لإعادة المشكلة"),
  expectedResult: z.string().min(5, "أضف النتيجة المتوقعة"),
  actualResult: z.string().min(5, "أضف النتيجة الفعلية"),
});
type ReportForm = z.infer<typeof reportSchema>;

const roleMeta: Record<"tester" | "client" | "community_manager" | "admin", { title: string; label: string; nav: DashboardNavItem[] }> = {
  tester: { title: "لوحة المختبر", label: "مساحة المختبر", nav: [{ label: "نظرة عامة", path: "/workspace", icon: LayoutDashboard }, { label: "تقاريري", path: "/workspace?section=reports", icon: FileWarning }, { label: "المحفظة", path: "/workspace?section=wallet", icon: WalletCards }, { label: "قيادة الاختبار", path: "/workspace?section=ttl", icon: ClipboardCheck }] },
  client: { title: "لوحة مالك الأعمال", label: "مساحة مالك الأعمال", nav: [{ label: "نظرة عامة", path: "/workspace", icon: LayoutDashboard }, { label: "المشاريع", path: "/workspace?section=projects", icon: FolderKanban }, { label: "التقارير المقبولة", path: "/workspace?section=accepted-reports", icon: CheckCircle2 }, { label: "المتقدمون والدعوات", path: "/workspace?section=participants", icon: UsersRound }] },
  community_manager: { title: "إدارة مجتمع المختبرين", label: "مدير المجتمع", nav: [{ label: "نظرة عامة", path: "/workspace", icon: LayoutDashboard }, { label: "قادة الاختبار", path: "/workspace?section=ttl-assignments", icon: UsersRound }, { label: "التحويلات", path: "/workspace?section=payouts", icon: Banknote }] },
  admin: { title: "إدارة المنصة", label: "مسؤول المنصة", nav: [{ label: "العمليات", path: "/workspace", icon: LayoutDashboard }, { label: "مديرو المجتمع", path: "/workspace#community-managers", icon: ShieldCheck }, { label: "طلبات السحب", path: "/workspace#payouts", icon: Banknote }] },
};

export default function Workspace() {
  const [location, setLocation] = useLocation();
  const search = useSearch();
  const { loading: authLoading, user } = useAuth();
  const profile = trpc.account.profile.useQuery(undefined, { enabled: !authLoading && Boolean(user) });
  const dashboard = trpc.workspace.dashboard.useQuery(undefined, { enabled: Boolean(profile.data && profile.data.role !== "user") });
  const notifications = trpc.notifications.list.useQuery(undefined, { enabled: Boolean(profile.data) });
  const ttlAssignments = trpc.ttl.assignedCycles.useQuery(undefined, { enabled: profile.data?.role === "tester" });
  const section = new URLSearchParams(search).get("section") ?? "overview";

  useEffect(() => {
    if (authLoading || !user || profile.isLoading) return;
    if (!profile.data || profile.data.role === "user") setLocation("/onboarding");
  }, [authLoading, profile.data, profile.isLoading, setLocation, user]);

  if (authLoading || (Boolean(user) && profile.isLoading)) return <WorkspaceLoading />;
  if (!user) return <WorkspaceAccessGate />;
  if (profile.error) return <WorkspaceProfileError onRetry={() => void profile.refetch()} />;
  if (!profile.data || profile.data.role === "user") return <OnboardingGate onContinue={() => setLocation("/onboarding")} />;
  const role = profile.data.role as keyof typeof roleMeta;
  const meta = roleMeta[role];
  if (!meta) return <WorkspaceProfileError onRetry={() => void profile.refetch()} />;
  const navItems = role === "tester" && !ttlAssignments.data?.length ? meta.nav.filter((item) => item.path !== "/workspace?section=ttl") : meta.nav;

  return <DashboardLayout title={meta.title} roleLabel={meta.label} navItems={navItems} notificationCount={notifications.data?.filter((item) => !item.readAt).length ?? 0} notifications={notifications.data ?? []}>
    {dashboard.isLoading ? <div className="grid gap-5 md:grid-cols-3"><SkeletonCard /><SkeletonCard /><SkeletonCard /></div> :
      role === "tester" ? <TesterWorkspace data={dashboard.data ?? {}} notifications={notifications.data ?? []} section={section} /> :
      role === "client" ? <ClientWorkspaceV2 data={dashboard.data ?? {}} notifications={notifications.data ?? []} section={section} /> :
      role === "community_manager" ? <CommunityManagerWorkspaceV2 data={dashboard.data ?? {}} section={section} /> :
      <AdminWorkspace data={dashboard.data ?? {}} notifications={notifications.data ?? []} />}
  </DashboardLayout>;
}

function WorkspaceLoading() { return <main aria-busy="true" className="min-h-screen bg-[#f8f4e9] p-6"><div className="mx-auto max-w-6xl space-y-5"><SkeletonCard /><div className="grid gap-5 md:grid-cols-3"><SkeletonCard /><SkeletonCard /><SkeletonCard /></div></div></main>; }
function WorkspaceAccessGate() { return <main dir="rtl" className="grid min-h-screen place-items-center bg-[#f8f4e9] p-6 text-right"><section className="surface-card w-full max-w-md p-8 text-center"><ShieldCheck className="mx-auto h-7 w-7 text-[#b8882e]" /><h1 className="mt-5 text-2xl font-bold text-[#102a43]">سجّل دخولك للمتابعة</h1><p className="mt-3 leading-7 text-[#58656f]">تحتاج إلى حساب موثّق للوصول إلى مساحة العمل وإدارة دورات الاختبار وتقارير الجودة.</p><Button className="mt-7 w-full bg-[#102a43] hover:bg-[#173a59]" onClick={() => window.location.assign("/sign-in")}>تسجيل الدخول</Button></section></main>; }
function OnboardingGate({ onContinue }: { onContinue: () => void }) { return <main dir="rtl" className="grid min-h-screen place-items-center bg-[#f8f4e9] p-6 text-right"><section className="surface-card w-full max-w-md p-8 text-center"><Smartphone className="mx-auto h-7 w-7 text-[#b8882e]" /><h1 className="mt-5 text-2xl font-bold text-[#102a43]">أكمل إعداد حسابك</h1><p className="mt-3 leading-7 text-[#58656f]">نحتاج معلومات الدور قبل فتح مساحة العمل المناسبة لك.</p><Button className="mt-7 w-full bg-[#102a43] hover:bg-[#173a59]" onClick={onContinue}>الانتقال إلى الإعداد</Button></section></main>; }
function WorkspaceProfileError({ onRetry }: { onRetry: () => void }) { return <main dir="rtl" className="grid min-h-screen place-items-center bg-[#f8f4e9] p-6 text-right"><section className="surface-card w-full max-w-md p-8 text-center"><AlertTriangle className="mx-auto h-7 w-7 text-[#b64c3a]" /><h1 className="mt-5 text-2xl font-bold text-[#102a43]">تعذر تحميل مساحة العمل</h1><p className="mt-3 leading-7 text-[#58656f]">لم نتمكن من التحقق من حالة الحساب الآن. أعد المحاولة دون إعادة إدخال بياناتك.</p><Button className="mt-7 w-full bg-[#102a43] hover:bg-[#173a59]" onClick={onRetry}>إعادة المحاولة</Button></section></main>; }

function TesterWorkspace({ data, notifications, section }: { data: any; notifications: any[]; section: string }) {
  const [reportOpen, setReportOpen] = useState(false);
  const [payoutOpen, setPayoutOpen] = useState(false);
  const utils = trpc.useUtils();
  const apply = trpc.tester.applyToCycle.useMutation({ onSuccess: () => { toast.success("تم إرسال طلب الانضمام وبات بانتظار القرار."); utils.workspace.dashboard.invalidate(); }, onError: (error) => toast.error(error.message) });
  const cycles = data.activeCycles ?? [];
  const acceptedCycles = cycles.filter((cycle: any) => cycle.applicationStatus === "accepted");
  const availableBalance = Number(data.wallet?.availableBalance || 0);
  const [location, setLocation] = useLocation();
  const selectedCycleId = new URLSearchParams(location.includes("?") ? location.slice(location.indexOf("?")) : "").get("cycle");
  const cycleDetails = trpc.tester.cycleDetails.useQuery({ testCycleId: selectedCycleId ?? "00000000-0000-0000-0000-000000000000" }, { enabled: Boolean(selectedCycleId) });
  if (section === "reports") return <TesterReportsView reports={data.reports ?? []} notifications={notifications} />;
  if (section === "wallet") return <TesterWalletView availableBalance={availableBalance} payoutHistory={data.payoutHistory ?? []} transactions={data.transactionsHistory ?? []} />;
  if (section === "ttl") return <TtlSection />;
  if (section === "cycle") return <TesterCycleDetailsView cycle={cycleDetails.data} loading={cycleDetails.isLoading} onBack={() => setLocation("/workspace")} />;
  return <div className="space-y-7">
    <section className="workspace-hero"><div><p className="eyebrow">قياس الأثر</p><h2>اختبر بعد القبول، وسجّل كل تفصيل.</h2><p>التقدم إلى الدورة يسبق الوصول للنسخة وإرسال التقارير. لا يُسمح بإرسال أي تقرير قبل قبولك.</p></div><Dialog open={reportOpen} onOpenChange={setReportOpen}><DialogTrigger asChild><Button className="bg-[#102a43] hover:bg-[#173a59]"><Plus className="h-4 w-4" />{acceptedCycles.length ? "تقرير خطأ جديد" : "راجع طلبات الانضمام"}</Button></DialogTrigger><DialogContent dir="rtl" className="max-h-[92vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>{acceptedCycles.length ? "إرسال تقرير خطأ" : "لا توجد دورة مقبولة"}</DialogTitle><DialogDescription>{acceptedCycles.length ? "ستُحفظ البيانات كما أدخلتها وتبقى الحالة معلّقة حتى مراجعة قائد فريق الاختبار." : "تقدم إلى دورة اختبار ثم انتظر قبول طلبك قبل إرسال التقرير."}</DialogDescription></DialogHeader><BugReportForm cycles={acceptedCycles} devices={data.devices ?? []} onDone={() => setReportOpen(false)} /></DialogContent></Dialog></section>
    <div className="grid gap-4 md:grid-cols-3"><Metric label="الرصيد المتاح" value={`${money(availableBalance)} EGP`} note="يشمل مكافآت التقارير المقبولة" icon={WalletCards} /><Metric label="تقاريري" value={String(data.reports?.length ?? 0)} note="محفوظة في حسابك" icon={FileWarning} /><Metric label="نقاط السمعة" value={String(data.profile?.reputationScore ?? 0)} note="تزداد للتقارير المقبولة" icon={ShieldCheck} /></div>
    <section className="grid gap-6"><Card className="surface-card"><CardHeader><p className="eyebrow">دورات الاختبار</p><CardTitle className="mt-1">تقدم أو تابع حالة طلبك</CardTitle></CardHeader><CardContent className="space-y-3">{cycles.length ? cycles.map((cycle: any) => <article key={cycle.id} className="rounded-2xl border border-[#ece2c9] p-4"><div className="flex items-start justify-between gap-3"><div><h3 className="font-bold">{cycle.title}</h3><p className="mt-1 text-sm text-[#77838c]">{cycle.projectName}</p></div><StatusBadge status={cycle.applicationStatus ?? "available"} /></div><p className="mt-3 text-sm leading-6 text-[#59656e]">{cycle.scopeDescription}</p><div className="mt-4 flex flex-wrap items-center gap-2">{cycle.applicationStatus === "accepted" ? <><Button size="sm" className="bg-[#1d6b4e] hover:bg-[#18583f]" onClick={() => setLocation(`/workspace?section=cycle&cycle=${cycle.id}`)}>تفاصيل الدورة</Button><span className="text-xs text-[#5b6d75]">ينتهي: {formatDate(cycle.endAt)}</span></> : cycle.applicationStatus === "pending" ? <p className="text-sm text-[#8a6c20]">طلبك قيد المراجعة.</p> : <Button size="sm" disabled={apply.isPending} onClick={() => apply.mutate({ testCycleId: cycle.id })}>{cycle.applicationStatus === "rejected" ? "إعادة التقدم" : "التقدم للدورة"}</Button>}</div></article>) : <Empty icon={TestTube2} text="لا توجد دورة اختبار نشطة حالياً." />}</CardContent></Card></section>
  </div>;
}

function TesterReportsView({ reports, notifications }: { reports: any[]; notifications: any[] }) {
  return <div className="space-y-6"><section className="workspace-hero"><div><p className="eyebrow">تقاريري</p><h2>البيانات المحفوظة وحالة المراجعة</h2><p>كل تقرير محفوظ يظهر هنا مع حالته وآخر ملاحظة من قائد فريق الاختبار.</p></div></section><section className="grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><Card className="surface-card"><CardHeader><CardTitle>التقارير المحفوظة</CardTitle></CardHeader><CardContent className="space-y-3">{reports.length ? reports.map((report: any) => <ReportRecord key={report.id} report={report} />) : <Empty icon={FileWarning} text="لم ترسل أي تقرير بعد." />}</CardContent></Card><NotificationList notifications={notifications} /></section></div>;
}

function TesterWalletView({ availableBalance, payoutHistory, transactions }: { availableBalance: number; payoutHistory: any[]; transactions: any[] }) {
  const [payoutOpen, setPayoutOpen] = useState(false);
  return <div className="space-y-6"><section className="workspace-hero"><div><p className="eyebrow">المحفظة</p><h2>الرصيد وطلبات السحب</h2><p>تعرض هذه الصفحة حالة التحويل وسجل العمليات المالي الخاص بحسابك.</p></div></section><Card className="surface-card"><CardHeader><CardTitle>الرصيد المتاح: {money(availableBalance)} EGP</CardTitle></CardHeader><CardContent><Dialog open={payoutOpen} onOpenChange={setPayoutOpen}><DialogTrigger asChild><Button className="bg-[#102a43] hover:bg-[#173a59]"><Banknote className="h-4 w-4" />طلب سحب</Button></DialogTrigger><DialogContent dir="rtl" className="sm:max-w-md"><DialogHeader><DialogTitle>طلب سحب</DialogTitle><DialogDescription>لن يتاح الإرسال إذا لم يكن لديك رصيد قابل للسحب.</DialogDescription></DialogHeader><PayoutForm available={availableBalance} onDone={() => setPayoutOpen(false)} /></DialogContent></Dialog></CardContent></Card><section className="grid gap-6 xl:grid-cols-2"><Card className="surface-card"><CardHeader><p className="eyebrow">طلبات السحب</p><CardTitle className="mt-1">حالة التحويل</CardTitle></CardHeader><CardContent className="space-y-3">{payoutHistory.length ? payoutHistory.map((item) => <article key={item.id} className="rounded-2xl border border-[#ece2c9] p-3"><div className="flex items-center justify-between gap-3"><p className="font-bold">{money(item.amount)} EGP</p><StatusBadge status={item.status} /></div><p className="mt-2 text-xs text-[#718089]">{item.method} · {formatDate(item.requestedAt)}</p>{item.processingNote ? <p className="mt-2 rounded-xl bg-[#f7f3e9] p-2 text-xs text-[#53656f]">{item.processingNote}</p> : <p className="mt-2 text-xs text-[#8a6c20]">بانتظار تأكيد مدير المجتمع لإرسال التحويل.</p>}</article>) : <Empty icon={Banknote} text="لا توجد طلبات سحب حتى الآن." />}</CardContent></Card><Card className="surface-card"><CardHeader><p className="eyebrow">سجل المعاملات</p><CardTitle className="mt-1">كل حركة مالية محفوظة</CardTitle></CardHeader><CardContent className="space-y-3">{transactions.length ? transactions.map((item) => <article key={item.id} className="rounded-2xl border border-[#ece2c9] p-3"><div className="flex items-center justify-between gap-3"><p className="font-semibold">{transactionLabel(item.type)}</p><span className={Number(item.amount) < 0 ? "text-[#a14a39]" : "text-[#1d6b4e]"}>{Number(item.amount) === 0 ? "—" : `${money(Math.abs(Number(item.amount)))} EGP`}</span></div><p className="mt-1 text-xs text-[#718089]">{item.note || "بدون ملاحظة"} · {formatDate(item.createdAt)}</p></article>) : <Empty icon={CircleDollarSign} text="سيظهر سجل العمليات عند إضافة مكافأة أو إرسال طلب سحب." />}</CardContent></Card></section></div>;
}

function TesterCycleDetailsView({ cycle, loading, onBack }: { cycle: any; loading: boolean; onBack: () => void }) {
  if (loading) return <div className="space-y-5"><SkeletonCard /><SkeletonCard /></div>;
  if (!cycle) return <div className="space-y-5"><Button variant="outline" onClick={onBack}>العودة إلى الدورات</Button><Empty icon={AlertTriangle} text="تعذر تحميل تفاصيل الدورة المقبولة." /></div>;
  return <div className="space-y-6"><Button variant="outline" className="border-[#cead59] text-[#72521a]" onClick={onBack}>العودة إلى الدورات</Button><section className="workspace-hero"><div><p className="eyebrow">دورة مقبولة</p><h2>{cycle.title}</h2><p>{cycle.projectName} · من {formatDate(cycle.startAt)} إلى {formatDate(cycle.endAt)}</p></div><StatusBadge status={cycle.status} /></section><section className="grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><Card className="surface-card"><CardHeader><p className="eyebrow">سياق الاختبار</p><CardTitle className="mt-1">النطاق والتعليمات</CardTitle></CardHeader><CardContent className="space-y-4"><div><p className="text-sm font-semibold text-[#334e68]">داخل النطاق</p><p className="mt-1 whitespace-pre-wrap text-sm leading-7 text-[#60707a]">{cycle.scopeDescription}</p></div><div><p className="text-sm font-semibold text-[#334e68]">خارج النطاق</p><p className="mt-1 whitespace-pre-wrap text-sm leading-7 text-[#60707a]">{cycle.outOfScope || "لا توجد قيود إضافية مسجلة."}</p></div><a className="inline-flex h-10 items-center rounded-xl bg-[#1d6b4e] px-4 text-sm font-semibold text-white hover:bg-[#18583f]" href={cycle.buildUrl} target="_blank" rel="noreferrer">فتح نسخة الاختبار</a></CardContent></Card><Card className="surface-card"><CardHeader><p className="eyebrow">المكافآت</p><CardTitle className="mt-1">حسب درجة الخطورة</CardTitle></CardHeader><CardContent className="space-y-3">{cycle.rates?.map((rate: any) => <div key={rate.severity} className="flex items-center justify-between rounded-xl bg-[#f7f3e9] p-3"><span>{severityLabel(rate.severity)}</span><strong>{money(rate.bountyAmount)} EGP</strong></div>)}</CardContent></Card></section></div>;
}

function BugReportForm({ cycles, devices, onDone }: { cycles: any[]; devices: any[]; onDone: () => void }) {
  const utils = trpc.useUtils(); const upload = trpc.tester.uploadEvidence.useMutation(); const submit = trpc.tester.submitReport.useMutation({ onSuccess: () => { toast.success("تم حفظ تقرير الخطأ بنجاح وبات بانتظار المراجعة."); utils.workspace.dashboard.invalidate(); onDone(); }, onError: (error) => toast.error(error.message) });
  const [files, setFiles] = useState<File[]>([]); const fileRef = useRef<HTMLInputElement>(null); const form = useForm<ReportForm>({ resolver: zodResolver(reportSchema), defaultValues: { testCycleId: cycles[0]?.id ?? "", deviceId: "", title: "", category: "functional", severity: "major", stepsToReproduce: "", expectedResult: "", actualResult: "" } });
  if (!cycles.length) return <Empty icon={AlertTriangle} text="لا توجد دورة مقبولة لإرسال تقرير فيها." />;
  const onSubmit = async (values: ReportForm) => { try { const attachmentIds: string[] = []; for (const file of files) attachmentIds.push((await upload.mutateAsync({ filename: file.name, mimeType: normalizeMime(file.type), base64: await fileToBase64(file) })).attachmentId); await submit.mutateAsync({ ...values, attachmentIds }); } catch (error: any) { toast.error(error.message || "تعذر رفع الأدلة."); } };
  return <form onSubmit={form.handleSubmit(onSubmit)} className="grid gap-4 sm:grid-cols-2"><Field label="دورة الاختبار" error={form.formState.errors.testCycleId?.message}><select required {...form.register("testCycleId")} className="rtl-select">{cycles.map((cycle: any) => <option key={cycle.id} value={cycle.id}>{cycle.title}</option>)}</select></Field><Field label="الجهاز" error={form.formState.errors.deviceId?.message}><select required {...form.register("deviceId")} className="rtl-select"><option value="">اختر جهازاً</option>{devices.map((device: any) => <option key={device.id} value={device.id}>{device.brandModel} · {device.osName} {device.osVersion}</option>)}</select></Field><Field className="sm:col-span-2" label="عنوان الخطأ" error={form.formState.errors.title?.message}><Input required {...form.register("title")} placeholder="مثال: التطبيق يتوقف عند تأكيد الدفع" /></Field><Field label="التصنيف"><select required {...form.register("category")} className="rtl-select"><option value="functional">Functional</option><option value="ui">UI</option><option value="performance">Performance</option><option value="crash">Crash</option></select></Field><Field label="الخطورة"><select required {...form.register("severity")} className="rtl-select"><option value="critical">Critical</option><option value="major">Major</option><option value="minor">Minor</option></select></Field><Field className="sm:col-span-2" label="خطوات إعادة المشكلة" error={form.formState.errors.stepsToReproduce?.message}><Textarea required {...form.register("stepsToReproduce")} rows={4} placeholder="1. افتح... 2. اضغط... 3. لاحظ..." /></Field><Field label="النتيجة المتوقعة" error={form.formState.errors.expectedResult?.message}><Textarea required {...form.register("expectedResult")} rows={4} /></Field><Field label="النتيجة الفعلية" error={form.formState.errors.actualResult?.message}><Textarea required {...form.register("actualResult")} rows={4} /></Field><div className="sm:col-span-2"><Label htmlFor="report-evidence">الأدلة (صور، فيديو، سجلات)</Label><p id="report-evidence-help" className="mt-1 text-xs text-[#9a8e6c]">PNG, JPG, MP4, TXT, ZIP — حتى 10MB لكل ملف</p><button type="button" onClick={() => fileRef.current?.click()} onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); setFiles((current) => [...current, ...Array.from(event.dataTransfer.files)].slice(0, 12)); }} className="mt-2 grid w-full place-items-center rounded-2xl border border-dashed border-[#d0b15e] bg-[#fffaf0] px-5 py-8 text-center text-sm text-[#806c3c] hover:bg-[#faf1d9]">اسحب الملفات هنا أو اخترها من جهازك</button><input ref={fileRef} id="report-evidence" aria-label="إرفاق أدلة لتقرير الخطأ" aria-describedby="report-evidence-help" type="file" className="hidden" multiple accept="image/png,image/jpeg,video/mp4,text/plain,application/zip" onChange={(event) => setFiles(Array.from(event.target.files ?? []).slice(0, 12))} />{files.length ? <p className="mt-2 text-xs text-[#6b7b84]">{files.map((file) => file.name).join("، ")}</p> : null}</div><Button disabled={submit.isPending || upload.isPending} className="sm:col-span-2 mt-2 bg-[#102a43] hover:bg-[#173a59]" type="submit">{submit.isPending || upload.isPending ? "يجري الحفظ الآمن..." : "إرسال التقرير"}</Button></form>;
}

function PayoutForm({ available, onDone }: { available: number; onDone: () => void }) { const utils = trpc.useUtils(); const request = trpc.tester.requestPayout.useMutation({ onSuccess: () => { toast.success("تم إرسال طلب السحب."); utils.workspace.dashboard.invalidate(); onDone(); }, onError: (error) => toast.error(error.message) }); const [amount, setAmount] = useState(""); const [method, setMethod] = useState<"instapay" | "vodafone_cash" | "paypal" | "bank_transfer">("instapay"); const [target, setTarget] = useState(""); if (available <= 0) return <Empty icon={AlertTriangle} text="لا يوجد رصيد قابل للسحب حالياً." />; const normalizedAmount = Number(normalizeArabicDigits(amount)); const canSubmit = normalizedAmount >= 1 && normalizedAmount <= available && target.trim().length > 0; return <form className="space-y-4" onSubmit={(event) => { event.preventDefault(); if (canSubmit) request.mutate({ amount: normalizedAmount, method, paymentTargetInfo: target }); }}><p className="rounded-xl bg-[#fff8e5] p-3 text-sm text-[#806c3c]">الرصيد المتاح: {money(available)} EGP</p><Field label="المبلغ"><Input required inputMode="decimal" type="text" value={amount} onChange={(event) => setAmount(event.target.value)} placeholder="مثال: ١٥٠ أو 150" /></Field><Field label="طريقة التحويل"><select required className="rtl-select" value={method} onChange={(event) => setMethod(event.target.value as typeof method)}><option value="instapay">Instapay</option><option value="vodafone_cash">Vodafone Cash</option><option value="paypal">PayPal</option><option value="bank_transfer">تحويل بنكي</option></select></Field><Field label="بيانات المستلم"><Input required value={target} onChange={(event) => setTarget(event.target.value)} /></Field><Button disabled={request.isPending || !canSubmit} className="w-full bg-[#102a43]">إرسال طلب السحب</Button></form>; }

function ClientWorkspace({ data, notifications }: { data: any; notifications: any[] }) { const [projectOpen, setProjectOpen] = useState(false); const [cycleOpen, setCycleOpen] = useState(false); return <div className="space-y-7"><section className="workspace-hero"><div><p className="eyebrow">تحكم مدروس</p><h2>ادعُ المختبرين واعتمد المشاركة.</h2><p>يتابع مالك الأعمال التقارير المقبولة، ويدعو المختبرين ويقبل طلباتهم أو يرفضها. مراجعة التقرير نفسها هي من صلاحية قائد فريق الاختبار المعين.</p></div><div className="flex flex-wrap gap-3"><Dialog open={projectOpen} onOpenChange={setProjectOpen}><DialogTrigger asChild><Button variant="outline" className="border-[#cead59] text-[#72521a]"><Plus className="h-4 w-4" />مشروع جديد</Button></DialogTrigger><DialogContent dir="rtl" className="sm:max-w-lg"><DialogHeader><DialogTitle>إنشاء مشروع</DialogTitle><DialogDescription>أضف وصفاً يوضح المنتج وسياق الاختبار.</DialogDescription></DialogHeader><ProjectForm onDone={() => setProjectOpen(false)} /></DialogContent></Dialog><Dialog open={cycleOpen} onOpenChange={setCycleOpen}><DialogTrigger asChild><Button className="bg-[#102a43] hover:bg-[#173a59]"><Plus className="h-4 w-4" />دورة اختبار</Button></DialogTrigger><DialogContent dir="rtl" className="max-h-[92vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>إنشاء دورة اختبار</DialogTitle><DialogDescription>حدد النطاق والجدول والمكافآت قبل إتاحة الدورة للمختبرين.</DialogDescription></DialogHeader><CycleForm projects={data.projects ?? []} onDone={() => setCycleOpen(false)} /></DialogContent></Dialog></div></section><div className="grid gap-4 md:grid-cols-3"><Metric label="المشاريع" value={String(data.projects?.length ?? 0)} note="ضمن حسابك" icon={FolderKanban} /><Metric label="دورات الاختبار" value={String(data.cycles?.length ?? 0)} note="مسودة أو نشطة" icon={TestTube2} /><Metric label="التقارير المقبولة" value={String(data.acceptedReports?.length ?? 0)} note="راجِع المخرجات المعتمدة" icon={CheckCircle2} /></div><section id="projects" className="scroll-mt-24 grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><Card className="surface-card"><CardHeader><p className="eyebrow">المشاريع</p><CardTitle className="mt-1">محفظة الاختبار</CardTitle></CardHeader><CardContent className="space-y-3">{data.projects?.length ? data.projects.map((project: any) => <article key={project.id} className="rounded-2xl border border-[#ece2c9] p-4"><h3 className="font-bold">{project.name}</h3><p className="mt-2 line-clamp-2 text-sm leading-6 text-[#68747d]">{project.description}</p></article>) : <Empty icon={FolderKanban} text="ابدأ بإنشاء مشروعك الأول." />}</CardContent></Card><Card className="surface-card"><CardHeader><p className="eyebrow">الدورات</p><CardTitle className="mt-1">نطاقات الاختبار</CardTitle></CardHeader><CardContent className="space-y-3">{data.cycles?.length ? data.cycles.map((cycle: any) => <article key={cycle.id} className="flex items-center justify-between rounded-2xl border border-[#ece2c9] p-4"><div><p className="font-semibold">{cycle.title}</p><p className="mt-1 text-xs text-[#718089]">حتى {formatDate(cycle.endAt)}</p></div><StatusBadge status={cycle.status} /></article>) : <Empty icon={TestTube2} text="لم تنشئ أي دورة اختبار بعد." />}</CardContent></Card></section><section id="accepted-reports" className="scroll-mt-24 grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><Card className="surface-card"><CardHeader><p className="eyebrow">التقارير المقبولة</p><CardTitle className="mt-1">نتائج جاهزة للأعمال</CardTitle></CardHeader><CardContent className="space-y-3">{data.acceptedReports?.length ? data.acceptedReports.map((report: any) => <ReportRecord key={report.id} report={report} showFull />) : <Empty icon={CheckCircle2} text="لا توجد تقارير مقبولة بعد." />}</CardContent></Card><NotificationList notifications={notifications} /></section><section id="participants" className="scroll-mt-24 grid gap-6 xl:grid-cols-2"><InvitationPanel cycles={data.cycles ?? []} /><ApplicationPanel cycles={data.cycles ?? []} owner /></section></div>; }

function ProjectForm({ onDone }: { onDone: () => void }) { const utils = trpc.useUtils(); const create = trpc.clientPortal.createProject.useMutation({ onSuccess: () => { toast.success("تم إنشاء المشروع."); utils.workspace.dashboard.invalidate(); onDone(); }, onError: (error) => toast.error(error.message) }); const [name, setName] = useState(""); const [description, setDescription] = useState(""); return <form onSubmit={(event) => { event.preventDefault(); create.mutate({ name, description }); }} className="space-y-4"><Field label="اسم المشروع"><Input required value={name} onChange={(event) => setName(event.target.value)} placeholder="اسم المنتج أو التطبيق" /></Field><Field label="وصف المشروع"><Textarea required minLength={20} value={description} onChange={(event) => setDescription(event.target.value)} rows={6} placeholder="عرّف المنتج وسياق الاختبار." /></Field><Button disabled={create.isPending} className="w-full bg-[#102a43]">إنشاء المشروع</Button></form>; }
function CycleForm({ projects, onDone }: { projects: any[]; onDone: () => void }) { const utils = trpc.useUtils(); const create = trpc.clientPortal.createCycle.useMutation({ onSuccess: () => { toast.success("تم إنشاء دورة الاختبار."); utils.workspace.dashboard.invalidate(); onDone(); }, onError: (error) => toast.error(error.message) }); const [form, setForm] = useState({ projectId: "", title: "", scopeDescription: "", outOfScope: "", buildUrl: "", status: "draft" as "draft" | "active", startAt: "", endAt: "", critical: "", major: "", minor: "" }); const set = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value })); return <form onSubmit={(event) => { event.preventDefault(); create.mutate({ projectId: form.projectId, title: form.title, scopeDescription: form.scopeDescription, outOfScope: form.outOfScope || undefined, buildUrl: form.buildUrl, status: form.status, startAt: new Date(form.startAt), endAt: new Date(form.endAt), rates: { critical: Number(form.critical), major: Number(form.major), minor: Number(form.minor) } }); }} className="grid gap-4 sm:grid-cols-2"><Field label="المشروع"><select required className="rtl-select" value={form.projectId} onChange={(event) => set("projectId", event.target.value)}><option value="">اختر مشروعاً</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></Field><Field label="الحالة"><select className="rtl-select" value={form.status} onChange={(event) => set("status", event.target.value)}><option value="draft">مسودة</option><option value="active">نشطة</option></select></Field><Field className="sm:col-span-2" label="عنوان الدورة"><Input required value={form.title} onChange={(event) => set("title", event.target.value)} /></Field><Field className="sm:col-span-2" label="النطاق داخل الاختبار"><Textarea required minLength={20} rows={3} value={form.scopeDescription} onChange={(event) => set("scopeDescription", event.target.value)} /></Field><Field className="sm:col-span-2" label="خارج النطاق"><Textarea rows={2} value={form.outOfScope} onChange={(event) => set("outOfScope", event.target.value)} /></Field><Field className="sm:col-span-2" label="رابط النسخة أو APK"><Input required type="url" value={form.buildUrl} onChange={(event) => set("buildUrl", event.target.value)} placeholder="https://" /></Field><Field label="تاريخ البداية"><Input required type="datetime-local" value={form.startAt} onChange={(event) => set("startAt", event.target.value)} /></Field><Field label="تاريخ الانتهاء"><Input required type="datetime-local" value={form.endAt} onChange={(event) => set("endAt", event.target.value)} /></Field><Field label="Critical (EGP)"><Input required min="1" type="number" value={form.critical} onChange={(event) => set("critical", event.target.value)} /></Field><Field label="Major (EGP)"><Input required min="1" type="number" value={form.major} onChange={(event) => set("major", event.target.value)} /></Field><Field label="Minor (EGP)"><Input required min="1" type="number" value={form.minor} onChange={(event) => set("minor", event.target.value)} /></Field><Button disabled={create.isPending || !projects.length} className="sm:col-span-2 bg-[#102a43]">إنشاء دورة الاختبار</Button>{!projects.length ? <p className="sm:col-span-2 text-sm text-[#ad5c43]">أنشئ مشروعاً أولاً قبل إضافة دورة اختبار.</p> : null}</form>; }

function InvitationPanel({ cycles }: { cycles: any[] }) { const utils = trpc.useUtils(); const [cycleId, setCycleId] = useState(""); const [testerEmail, setTesterEmail] = useState(""); const testers = trpc.clientPortal.eligibleTesters.useQuery(); const invite = trpc.clientPortal.inviteTester.useMutation({ onSuccess: () => { toast.success("تمت دعوة المختبر للتقدم إلى الدورة."); setTesterEmail(""); utils.workspace.dashboard.invalidate(); }, onError: (error) => toast.error(error.message) }); const inviteByEmail = () => { const email = testerEmail.trim().toLowerCase(); if (!cycleId || !email) return; invite.mutate({ testCycleId: cycleId, testerEmail: email }); }; return <Card className="surface-card"><CardHeader><p className="eyebrow">دعوات الاختبار</p><CardTitle className="mt-1">ادعُ مختبراً للتقدم</CardTitle></CardHeader><CardContent className="space-y-3"><select className="rtl-select" value={cycleId} onChange={(event) => setCycleId(event.target.value)}><option value="">اختر دورة اختبار</option>{cycles.map((cycle) => <option key={cycle.id} value={cycle.id}>{cycle.title}</option>)}</select>{!cycles.length ? <Empty icon={UsersRound} text="أنشئ دورة اختبار أولاً." /> : <><div className="rounded-2xl border border-[#ece2c9] bg-[#fffcf4] p-3"><Field label="بريد المختبر"><Input type="email" value={testerEmail} onChange={(event) => setTesterEmail(event.target.value)} placeholder="tester@example.com" /></Field><Button size="sm" className="mt-3 w-full bg-[#102a43]" disabled={!cycleId || !testerEmail.trim() || invite.isPending} onClick={inviteByEmail}>إرسال الدعوة بالبريد</Button></div><p className="pt-1 text-xs font-semibold text-[#8a6c20]">أو اختر مختبراً مؤهلاً من القائمة:</p>{testers.isLoading ? <SkeletonCard /> : testers.data?.length ? testers.data.map((tester) => <article key={tester.id} className="flex items-center justify-between gap-3 rounded-2xl border border-[#ece2c9] p-3"><div><p className="font-semibold">{tester.name || tester.email || "حساب مختبر"}</p><p className="text-xs text-[#77838c]">{tester.email || "بلا بريد ظاهر"} · سمعة: {tester.reputationScore ?? 0}</p></div><Button size="sm" disabled={!cycleId || invite.isPending} onClick={() => invite.mutate({ testCycleId: cycleId, testerId: tester.id })}>دعوة</Button></article>) : <Empty icon={UsersRound} text="لا يوجد مختبرون مكتملو الملف حالياً." />}</>}</CardContent></Card>; }

function ApplicationPanel({ cycles, owner = false, ttl = false }: { cycles: any[]; owner?: boolean; ttl?: boolean }) { const utils = trpc.useUtils(); const [cycleId, setCycleId] = useState(""); const query = owner ? trpc.clientPortal.cycleApplications.useQuery({ testCycleId: cycleId }, { enabled: Boolean(cycleId) }) : trpc.ttl.cycleApplications.useQuery({ testCycleId: cycleId }, { enabled: Boolean(cycleId) }); const decide = owner ? trpc.clientPortal.decideApplication.useMutation({ onSuccess: () => { toast.success("تم حفظ قرار طلب الانضمام."); utils.workspace.dashboard.invalidate(); query.refetch(); }, onError: (error) => toast.error(error.message) }) : trpc.ttl.decideApplication.useMutation({ onSuccess: () => { toast.success("تم حفظ قرار طلب الانضمام."); utils.workspace.dashboard.invalidate(); query.refetch(); }, onError: (error) => toast.error(error.message) }); return <Card className="surface-card"><CardHeader><p className="eyebrow">طلبات الانضمام</p><CardTitle className="mt-1">قبول أو رفض المختبرين</CardTitle></CardHeader><CardContent className="space-y-3"><select className="rtl-select" value={cycleId} onChange={(event) => setCycleId(event.target.value)}><option value="">اختر دورة اختبار</option>{cycles.map((cycle) => <option key={cycle.id} value={cycle.id}>{cycle.title}</option>)}</select>{!cycleId ? <p className="text-sm text-[#77838c]">اختر دورة لعرض طلباتها.</p> : query.data?.length ? query.data.map((application) => <ApplicationDecision key={application.id} application={application} busy={decide.isPending} onDecide={(decision, reason) => decision === "accepted" ? decide.mutate({ applicationId: application.id, decision }) : decide.mutate({ applicationId: application.id, decision, reason: reason ?? "" })} />) : <Empty icon={CheckCircle2} text="لا توجد طلبات لهذه الدورة." />}</CardContent></Card>; }

function ApplicationDecision({ application, onDecide, busy }: { application: any; onDecide: (decision: "accepted" | "rejected", reason?: string) => void; busy: boolean }) { const [reason, setReason] = useState(""); return <article className="rounded-2xl border border-[#ece2c9] p-3"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{application.testerName || application.testerEmail || "حساب مختبر"}</p><p className="mt-1 text-xs text-[#77838c]">{application.testerEmail || "بلا بريد ظاهر"} · سمعة: {application.reputationScore ?? 0} · {formatDate(application.appliedAt)}</p></div><StatusBadge status={application.status} /></div>{application.status === "pending" ? <div className="mt-3 space-y-2"><Textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={2} placeholder="سبب الرفض عند الحاجة" /><div className="flex gap-2"><Button size="sm" disabled={busy} className="bg-[#1d6b4e] hover:bg-[#18583f]" onClick={() => onDecide("accepted")}>قبول</Button><Button size="sm" variant="outline" disabled={busy || reason.trim().length < 12} className="border-[#d59a83] text-[#aa4f37]" onClick={() => onDecide("rejected", reason)}>رفض</Button></div></div> : application.decisionReason ? <p className="mt-2 text-xs text-[#aa4f37]">سبب القرار: {application.decisionReason}</p> : null}</article>; }

function TtlSection() { const assigned = trpc.ttl.assignedCycles.useQuery(); const [cycleId, setCycleId] = useState(""); const reports = trpc.ttl.pendingReports.useQuery({ testCycleId: cycleId }, { enabled: Boolean(cycleId) }); const utils = trpc.useUtils(); const review = trpc.ttl.reviewBug.useMutation({ onSuccess: () => { toast.success("تم حفظ قرار المراجعة وإرسال إشعار للمختبر."); utils.workspace.dashboard.invalidate(); reports.refetch(); }, onError: (error) => toast.error(error.message) }); if (!assigned.data?.length) return null; return <section id="ttl" className="scroll-mt-24 grid gap-6 xl:grid-cols-2"><Card className="surface-card"><CardHeader><p className="eyebrow">دور قائد فريق الاختبار</p><CardTitle className="mt-1">مراجعة التقارير المعلقة</CardTitle></CardHeader><CardContent className="space-y-3"><select className="rtl-select" value={cycleId} onChange={(event) => setCycleId(event.target.value)}><option value="">اختر دورة معيّناً فيها</option>{assigned.data.map((cycle) => <option key={cycle.id} value={cycle.id}>{cycle.title} · {cycle.projectName}</option>)}</select>{cycleId && (reports.data?.length ? reports.data.map((report) => <TtlReviewCard key={report.id} report={report} busy={review.isPending} onReview={(action, reason) => action === "accepted" ? review.mutate({ bugId: report.id, action }) : review.mutate({ bugId: report.id, action, reason: reason ?? "" })} />) : <Empty icon={ClipboardCheck} text="لا توجد تقارير معلقة في هذه الدورة." />)}</CardContent></Card><ApplicationPanel cycles={assigned.data} ttl /></section>; }

function TtlReviewCard({ report, onReview, busy }: { report: any; onReview: (action: "accepted" | "rejected" | "request_information", reason?: string) => void; busy: boolean }) { const [reason, setReason] = useState(""); return <article className="rounded-2xl border border-[#ece2c9] p-4"><ReportRecord report={report} showFull /><Textarea className="mt-3" value={reason} onChange={(event) => setReason(event.target.value)} rows={2} placeholder="سبب الرفض أو المعلومات المطلوبة" /><div className="mt-3 flex flex-wrap gap-2"><Button size="sm" disabled={busy} className="bg-[#1d6b4e] hover:bg-[#18583f]" onClick={() => onReview("accepted")}>قبول التقرير</Button><Button size="sm" disabled={busy || reason.trim().length < 12} variant="outline" className="border-[#d3b768] text-[#7d6021]" onClick={() => onReview("request_information", reason)}>طلب معلومات</Button><Button size="sm" disabled={busy || reason.trim().length < 12} variant="outline" className="border-[#d59a83] text-[#aa4f37]" onClick={() => onReview("rejected", reason)}>رفض</Button></div></article>; }

function CommunityManagerWorkspace({ data }: { data: any; notifications: any[] }) { const utils = trpc.useUtils(); const [cycleId, setCycleId] = useState(""); const [testerId, setTesterId] = useState(""); const testers = trpc.communityManager.eligibleTesters.useQuery(); const ttls = trpc.communityManager.cycleTtls.useQuery({ testCycleId: cycleId }, { enabled: Boolean(cycleId) }); const assign = trpc.communityManager.assignTtl.useMutation({ onSuccess: () => { toast.success("تم تحديث تعيين قائد فريق الاختبار."); ttls.refetch(); utils.workspace.dashboard.invalidate(); }, onError: (error) => toast.error(error.message) }); return <div className="space-y-7"><section className="workspace-hero"><div><p className="eyebrow">حوكمة المجتمع</p><h2>إدارة قادة الاختبار والتحويلات.</h2><p>تظل الصلاحيات والمعاملات خاضعة للتحقق الخادمي وسجل الأحداث.</p></div><Badge className="bg-[#f5e7ba] text-[#72521a]">صلاحية خاضعة للخادم</Badge></section><div className="grid gap-4 md:grid-cols-2"><Metric label="طلبات التحويل المعلقة" value={String(data.pendingPayouts?.length ?? 0)} note="تحتاج تأكيد الإرسال" icon={Banknote} /><Metric label="معاملات المختبرين" value={String(data.transactionsHistory?.length ?? 0)} note="آخر 100 حركة مالية" icon={CircleDollarSign} /></div><section id="ttl-assignments" className="scroll-mt-24 grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><Card className="surface-card"><CardHeader><p className="eyebrow">تعيين TTL</p><CardTitle className="mt-1">اختبر الصلاحية حسب الدورة</CardTitle></CardHeader><CardContent className="space-y-3"><select className="rtl-select" value={cycleId} onChange={(event) => setCycleId(event.target.value)}><option value="">اختر دورة اختبار</option>{(data.cycles ?? []).map((cycle: any) => <option key={cycle.id} value={cycle.id}>{cycle.title} · {cycle.projectName}</option>)}</select><select className="rtl-select" value={testerId} onChange={(event) => setTesterId(event.target.value)}><option value="">اختر مختبراً مكتمل الملف</option>{testers.data?.map((tester) => <option key={tester.id} value={tester.id}>{tester.name || tester.email || "حساب مختبر"} · سمعة {tester.reputationScore ?? 0}</option>)}</select><Button disabled={!cycleId || !testerId || assign.isPending} className="w-full bg-[#102a43]" onClick={() => assign.mutate({ testCycleId: cycleId, testerId, assign: true })}>تعيين قائد فريق الاختبار</Button></CardContent></Card><Card className="surface-card"><CardHeader><p className="eyebrow">القادة الحاليون</p><CardTitle className="mt-1">تعيينات الدورة</CardTitle></CardHeader><CardContent className="space-y-3">{!cycleId ? <Empty icon={UsersRound} text="اختر دورة لعرض القادة المعينين." /> : ttls.data?.length ? ttls.data.map((ttl) => <article key={ttl.id} className="flex items-center justify-between gap-3 rounded-2xl border border-[#ece2c9] p-3"><div><p className="font-semibold">{ttl.testerName || ttl.testerEmail || "حساب مختبر"}</p><p className="text-xs text-[#77838c]">سمعة: {ttl.reputationScore ?? 0}</p></div><Button size="sm" variant="outline" disabled={assign.isPending} className="border-[#d59a83] text-[#aa4f37]" onClick={() => assign.mutate({ testCycleId: cycleId, testerId: ttl.testerId, assign: false })}>إزالة</Button></article>) : <Empty icon={UsersRound} text="لم يُعيّن قائد اختبار لهذه الدورة بعد." />}</CardContent></Card></section><section id="payouts" className="scroll-mt-24 grid gap-6 xl:grid-cols-2"><Card className="surface-card"><CardHeader><p className="eyebrow">طلبات السحب</p><CardTitle className="mt-1">تأكيد إرسال التحويل</CardTitle></CardHeader><CardContent className="space-y-3">{data.pendingPayouts?.length ? data.pendingPayouts.map((item: any) => <CommunityPayoutReview key={item.id} request={item} />) : <Empty icon={Banknote} text="لا توجد طلبات سحب معلقة." />}</CardContent></Card><Card className="surface-card"><CardHeader><p className="eyebrow">سجل كل المختبرين</p><CardTitle className="mt-1">المعاملات المالية</CardTitle></CardHeader><CardContent className="space-y-3">{data.transactionsHistory?.length ? data.transactionsHistory.map((item: any) => <article key={item.id} className="rounded-2xl border border-[#ece2c9] p-3"><div className="flex items-center justify-between gap-3"><p className="font-semibold">{item.testerName || item.testerEmail || "حساب مختبر"}</p><span className={Number(item.amount) < 0 ? "text-[#a14a39]" : "text-[#1d6b4e]"}>{Number(item.amount) === 0 ? "—" : `${money(Math.abs(Number(item.amount)))} EGP`}</span></div><p className="mt-1 text-xs text-[#718089]">{transactionLabel(item.type)} · {item.note || "بدون ملاحظة"} · {formatDate(item.createdAt)}</p></article>) : <Empty icon={CircleDollarSign} text="لا توجد معاملات مسجلة بعد." />}</CardContent></Card></section></div>; }

function AdminWorkspace({ data, notifications }: { data: any; notifications: any[] }) { const utils = trpc.useUtils(); const [targetId, setTargetId] = useState(""); const users = trpc.roles.assignableUsers.useQuery(); const setManager = trpc.roles.setCommunityManager.useMutation({ onSuccess: () => { toast.success("تم تحديث دور مدير المجتمع."); users.refetch(); utils.workspace.dashboard.invalidate(); }, onError: (error) => toast.error(error.message) }); return <div className="space-y-7"><section className="workspace-hero"><div><p className="eyebrow">إدارة المنصة</p><h2>توزيع أدوار لا يمكن تزويرها من المتصفح.</h2><p>لا يقبل الخادم أي دور مرسل من المستخدم؛ مدير المنصة فقط يستطيع إنشاء أو إلغاء دور مدير المجتمع.</p></div><Badge className="bg-[#f5e7ba] text-[#72521a]">تحكم خادمي</Badge></section><div className="grid gap-4 md:grid-cols-3"><Metric label="مديرو المجتمع" value={String(data.communityManagers?.length ?? 0)} note="يُعيّنون TTL فقط" icon={UsersRound} /><Metric label="طلبات السحب" value={String(data.pendingPayouts?.length ?? 0)} note="تحتاج معالجة" icon={Banknote} /><Metric label="التحكم بالأدوار" value="مؤمّن" note="هوية الخادم هي المرجع" icon={ShieldCheck} /></div><section id="community-managers" className="scroll-mt-24 grid gap-6 xl:grid-cols-2"><Card className="surface-card"><CardHeader><p className="eyebrow">إسناد مدير مجتمع</p><CardTitle className="mt-1">إنشاء صلاحية محددة</CardTitle></CardHeader><CardContent className="space-y-3"><select className="rtl-select" value={targetId} onChange={(event) => setTargetId(event.target.value)}><option value="">اختر حساباً</option>{users.data?.map((account) => <option key={account.id} value={account.id}>{account.name || account.email || account.id} · {account.role}</option>)}</select><Button disabled={!targetId || setManager.isPending} className="w-full bg-[#102a43]" onClick={() => setManager.mutate({ targetUserId: targetId, enabled: true })}>منح دور مدير المجتمع</Button></CardContent></Card><Card className="surface-card"><CardHeader><p className="eyebrow">الحاليون</p><CardTitle className="mt-1">مديرو المجتمع المعينون</CardTitle></CardHeader><CardContent className="space-y-3">{data.communityManagers?.length ? data.communityManagers.map((manager: any) => <article key={manager.id} className="flex items-center justify-between gap-3 rounded-2xl border border-[#ece2c9] p-3"><p className="font-semibold">{manager.name || manager.email || "حساب"}</p><Button size="sm" variant="outline" disabled={setManager.isPending} className="border-[#d59a83] text-[#aa4f37]" onClick={() => setManager.mutate({ targetUserId: manager.id, enabled: false })}>إلغاء الدور</Button></article>) : <Empty icon={UsersRound} text="لا يوجد مدير مجتمع معيّن." />}</CardContent></Card></section><section id="payouts" className="scroll-mt-24 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Card className="surface-card"><CardHeader><p className="eyebrow">طلبات السحب</p><CardTitle className="mt-1">المعالجة المالية</CardTitle></CardHeader><CardContent className="space-y-3">{data.pendingPayouts?.length ? data.pendingPayouts.map((item: any) => <PayoutReview key={item.id} request={item} />) : <Empty icon={Banknote} text="لا توجد طلبات سحب معلقة." />}</CardContent></Card><NotificationList notifications={notifications} /></section></div>; }

function PayoutReview({ request }: { request: any }) { const utils = trpc.useUtils(); const process = trpc.admin.processPayout.useMutation({ onSuccess: () => { toast.success("تمت معالجة الطلب."); utils.workspace.dashboard.invalidate(); }, onError: (error) => toast.error(error.message) }); const [note, setNote] = useState(""); return <article className="rounded-2xl border border-[#ece2c9] p-4"><div className="flex items-center justify-between"><span className="font-bold">{money(request.amount)} EGP</span><Badge className="bg-[#f5edd3] text-[#795d1f]">{request.method}</Badge></div><p className="mt-2 text-xs text-[#748089]">الوجهة: {request.paymentTargetInfo}</p><Input className="mt-3" value={note} onChange={(event) => setNote(event.target.value)} placeholder="ملاحظة المعالجة" /><div className="mt-2 flex gap-2"><Button size="sm" disabled={note.trim().length < 3 || process.isPending} className="bg-[#1d6b4e] hover:bg-[#18583f]" onClick={() => process.mutate({ payoutId: request.id, decision: "processed", note })}>تمت المعالجة</Button><Button size="sm" disabled={note.trim().length < 3 || process.isPending} variant="outline" className="border-[#d59a83] text-[#aa4f37]" onClick={() => process.mutate({ payoutId: request.id, decision: "rejected", note })}>رفض</Button></div></article>; }
function CommunityPayoutReview({ request }: { request: any }) { const utils = trpc.useUtils(); const process = trpc.communityManager.processPayout.useMutation({ onSuccess: () => { toast.success("تم تأكيد إرسال التحويل وسُجلت العملية."); utils.workspace.dashboard.invalidate(); }, onError: (error) => toast.error(error.message) }); const [note, setNote] = useState(""); return <article className="rounded-2xl border border-[#ece2c9] p-4"><div className="flex items-center justify-between gap-3"><div><p className="font-semibold">{request.testerName || request.testerEmail || "حساب مختبر"}</p><p className="mt-1 text-xs text-[#748089]">{request.testerEmail || ""}</p></div><span className="font-bold">{money(request.amount)} EGP</span></div><p className="mt-2 text-xs text-[#748089]">{request.method} · الوجهة: {request.paymentTargetInfo}</p><Input className="mt-3" value={note} onChange={(event) => setNote(event.target.value)} placeholder="رقم مرجع التحويل أو ملاحظة الإرسال" /><div className="mt-2 flex gap-2"><Button size="sm" disabled={note.trim().length < 3 || process.isPending} className="bg-[#1d6b4e] hover:bg-[#18583f]" onClick={() => process.mutate({ payoutId: request.id, decision: "processed", note })}>تم الإرسال</Button><Button size="sm" disabled={note.trim().length < 3 || process.isPending} variant="outline" className="border-[#d59a83] text-[#aa4f37]" onClick={() => process.mutate({ payoutId: request.id, decision: "rejected", note })}>رفض</Button></div></article>; }

function ReportRecord({ report, showFull = false }: { report: any; showFull?: boolean }) {
  const [open, setOpen] = useState(false);
  const detail = showFull || open;
  const presentation = buildReportPresentation(report);
  return <article className="rounded-2xl border border-[#eee5d1] p-4"><div className="flex items-start justify-between gap-4"><div><p className="font-semibold">{presentation.title}</p><p className="mt-1 text-xs text-[#78848c]">{categoryLabel(report.category)} · {severityLabel(report.severity)} · {formatDate(report.createdAt)}</p></div><StatusBadge status={report.status} /></div>{detail ? <div className="mt-3 grid gap-2 text-sm leading-6 text-[#64737c]">{presentation.details.map((item) => <p key={item.id}><strong className="text-[#334e68]">{item.label}: </strong>{item.value}</p>)}{report.requestChangesReason ? <p className="rounded-xl bg-[#fff8e5] p-2 text-[#806c3c]"><strong>معلومات مطلوبة: </strong>{report.requestChangesReason}</p> : null}{report.rejectionReason ? <p className="rounded-xl bg-[#fff0ee] p-2 text-[#a14a39]"><strong>سبب الرفض: </strong>{report.rejectionReason}</p> : null}{report.attachments?.length ? <div className="mt-2 rounded-xl bg-[#f7f3e9] p-3"><p className="font-semibold text-[#334e68]">الأدلة المرفقة</p><div className="mt-2 grid gap-3 sm:grid-cols-2">{report.attachments.map((attachment: any) => <ReportAttachment key={attachment.id} attachment={attachment} />)}</div></div> : null}{presentation.history.length ? <div className="mt-2 rounded-xl bg-[#f7f3e9] p-3"><p className="font-semibold text-[#334e68]">سجل الحالة</p><ol className="mt-2 space-y-1">{presentation.history.map((event) => <li key={event.id} className="text-xs"><span className="font-medium text-[#4d5f6f]">{event.label}</span>{event.message ? ` — ${event.message}` : ""}<span className="mr-2 text-[#78848c]">{formatDate(event.createdAt)}</span></li>)}</ol></div> : null}</div> : null}{!showFull ? <Button variant="ghost" size="sm" className="mt-2 px-0 text-[#72521a]" onClick={() => setOpen((current) => !current)}>{open ? "إخفاء التفاصيل" : "عرض البيانات المحفوظة"}</Button> : null}</article>;
}
function ReportAttachment({ attachment }: { attachment: any }) { const file = trpc.evidence.getSecureUrl.useQuery({ attachmentId: attachment.id }); if (file.isLoading) return <div className="rounded-xl border border-[#e6dbbe] p-3 text-xs text-[#77838c]">جارٍ تحميل الدليل…</div>; if (!file.data) return <div className="rounded-xl border border-[#e6dbbe] p-3 text-xs text-[#a14a39]">تعذر تحميل الدليل.</div>; const image = String(attachment.mimeType).startsWith("image/"); return <a href={file.data.url} target="_blank" rel="noreferrer" className="block overflow-hidden rounded-xl border border-[#e6dbbe] bg-white text-xs text-[#526674] hover:border-[#caa754]">{image ? <img src={file.data.url} alt={attachment.originalName} className="h-36 w-full object-cover" /> : <div className="grid h-24 place-items-center p-3"><span>{attachment.originalName}</span></div>}<p className="truncate p-2 font-medium">{attachment.originalName}</p></a>; }
function NotificationList({ notifications }: { notifications: any[] }) { return <Card className="surface-card"><CardHeader><p className="eyebrow">مركز الإشعارات</p><CardTitle className="mt-1">آخر المستجدات</CardTitle></CardHeader><CardContent className="space-y-3">{notifications.length ? notifications.slice(0, 5).map((item) => <article key={item.id} className="rounded-2xl border border-[#eee5d1] p-3"><p className="text-sm font-bold">{item.title}</p><p className="mt-1 text-xs leading-5 text-[#77838c]">{item.body}</p></article>) : <Empty icon={Bell} text="ستظهر هنا تحديثات الحالات والدفعات." />}</CardContent></Card>; }
function Metric({ label, value, note, icon: Icon }: { label: string; value: string; note: string; icon: any }) { return <Card className="surface-card overflow-hidden"><CardContent className="relative p-5"><Icon className="absolute left-4 top-4 h-16 w-16 text-[#dfc26d]/25" /><p className="text-sm font-semibold text-[#6b7880]">{label}</p><p className="mt-2 text-3xl font-extrabold tracking-tight text-[#102a43]">{value}</p><p className="mt-1 text-xs text-[#9a8050]">{note}</p></CardContent></Card>; }
function StatusBadge({ status }: { status: string }) { const map: Record<string, [string, string]> = { pending: ["معلّق", "bg-[#f6e8b7] text-[#7c6225]"], accepted: ["مقبول", "bg-[#dcece2] text-[#336648]"], rejected: ["مرفوض", "bg-[#f4dedd] text-[#9a3d3b]"], processed: ["تم الإرسال", "bg-[#dcece2] text-[#336648]"], available: ["متاحة للتقدم", "bg-[#e8edf1] text-[#50616e]"], active: ["نشطة", "bg-[#dcece2] text-[#336648]"], draft: ["مسودة", "bg-[#e8edf1] text-[#50616e]"], in_review: ["قيد المراجعة", "bg-[#f6e8b7] text-[#7c6225]"], completed: ["مكتملة", "bg-[#e8edf1] text-[#50616e]"] }; const [label, classes] = map[status] ?? [status, "bg-[#e8edf1] text-[#50616e]"]; return <Badge className={classes}>{label}</Badge>; }
function Empty({ icon: Icon, text }: { icon: any; text: string }) { return <div className="grid place-items-center rounded-2xl border border-dashed border-[#dfd2ae] bg-[#fffcf4] px-5 py-10 text-center"><Icon className="h-6 w-6 text-[#c8a850]" /><p className="mt-3 text-sm text-[#758189]">{text}</p></div>; }
function SkeletonCard() { return <div className="h-32 animate-pulse rounded-3xl bg-[#eee4ca]" />; }
function Field({ label, children, error, className = "" }: { label: string; children: React.ReactNode; error?: unknown; className?: string }) { const message = typeof error === "object" && error && "message" in error ? String((error as { message?: string }).message ?? "") : String(error ?? ""); return <label className={`block ${className}`}><span className="mb-1.5 block text-sm font-semibold text-[#334e68]">{label}</span>{children}{message ? <span className="mt-1 block text-xs text-[#b64c3a]">{message}</span> : null}</label>; }
function categoryLabel(value: string) { return ({ functional: "Functional", ui: "UI", performance: "Performance", crash: "Crash" } as Record<string, string>)[value] ?? value; }
function severityLabel(value: string) { return ({ critical: "Critical", major: "Major", minor: "Minor" } as Record<string, string>)[value] ?? value; }
function transactionLabel(value: string) { return ({ bounty_pending: "مكافأة معلقة", bounty_released: "مكافأة تقرير مقبول", payout_debit: "طلب سحب", payout_reversal: "استرداد طلب سحب", payout_sent: "تم إرسال التحويل" } as Record<string, string>)[value] ?? value; }
function normalizeArabicDigits(value: string) { const arabic = "٠١٢٣٤٥٦٧٨٩"; const persian = "۰۱۲۳۴۵۶۷۸۹"; return value.replace(/[٠-٩]/g, (digit) => String(arabic.indexOf(digit))).replace(/[۰-۹]/g, (digit) => String(persian.indexOf(digit))).replace(/،/g, ".").replace(/٫/g, "."); }
function money(value: unknown) { return Number(value || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function formatDate(value: unknown) { return value ? new Date(value as string | number | Date).toLocaleDateString("ar-EG", { day: "numeric", month: "short", year: "numeric" }) : "—"; }
function normalizeMime(type: string) { return (["image/png", "image/jpeg", "video/mp4", "text/plain", "application/zip"].includes(type) ? type : "text/plain") as "image/png" | "image/jpeg" | "video/mp4" | "text/plain" | "application/zip"; }
function fileToBase64(file: File) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file); }); }

function ClientWorkspaceV2({ data, notifications, section }: { data: any; notifications: any[]; section: string }) {
  if (section === "projects") return <ClientProjectsSection data={data} />;
  if (section === "accepted-reports") return <ClientAcceptedReportsSection reports={data.acceptedReports ?? []} />;
  if (section === "participants") return <ClientParticipantsSection cycles={data.cycles ?? []} />;
  return <div className="space-y-7"><section className="workspace-hero"><div><p className="eyebrow">نظرة مالك الأعمال</p><h2>تابع مؤشرات الاختبار دون ازدحام التفاصيل.</h2><p>استخدم القائمة للوصول إلى المشاريع، التقارير المقبولة، أو المتقدمين والدعوات.</p></div><Badge className="bg-[#f5e7ba] text-[#72521a]">منظور مبسّط</Badge></section><div className="grid gap-4 md:grid-cols-3"><Metric label="المشاريع" value={String(data.projects?.length ?? 0)} note="انتقل إلى المشاريع للإدارة" icon={FolderKanban} /><Metric label="دورات الاختبار" value={String(data.cycles?.length ?? 0)} note="تظهر ضمن المشاريع" icon={TestTube2} /><Metric label="التقارير المقبولة" value={String(data.acceptedReports?.length ?? 0)} note="تظهر في قائمتها الخاصة" icon={CheckCircle2} /></div><NotificationList notifications={notifications} /></div>;
}

function ClientProjectsSection({ data }: { data: any }) {
  const [projectOpen, setProjectOpen] = useState(false); const [cycleOpen, setCycleOpen] = useState(false);
  return <div className="space-y-6"><section className="workspace-hero"><div><p className="eyebrow">المشاريع والدورات</p><h2>نطاق الاختبار ومكافآته.</h2><p>أنشئ المشاريع والدورات ثم انتقل إلى الدعوات لمتابعة المختبرين.</p></div><div className="flex flex-wrap gap-3"><Dialog open={projectOpen} onOpenChange={setProjectOpen}><DialogTrigger asChild><Button variant="outline" className="border-[#cead59] text-[#72521a]"><Plus className="h-4 w-4" />مشروع جديد</Button></DialogTrigger><DialogContent dir="rtl" className="sm:max-w-lg"><DialogHeader><DialogTitle>إنشاء مشروع</DialogTitle><DialogDescription>أضف وصفاً يوضح المنتج وسياق الاختبار.</DialogDescription></DialogHeader><ProjectForm onDone={() => setProjectOpen(false)} /></DialogContent></Dialog><Dialog open={cycleOpen} onOpenChange={setCycleOpen}><DialogTrigger asChild><Button className="bg-[#102a43] hover:bg-[#173a59]"><Plus className="h-4 w-4" />دورة اختبار</Button></DialogTrigger><DialogContent dir="rtl" className="max-h-[92vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>إنشاء دورة اختبار</DialogTitle><DialogDescription>حدد النطاق والجدول والمكافآت قبل إتاحة الدورة للمختبرين.</DialogDescription></DialogHeader><CycleForm projects={data.projects ?? []} onDone={() => setCycleOpen(false)} /></DialogContent></Dialog></div></section><section className="grid gap-6 xl:grid-cols-2"><Card className="surface-card"><CardHeader><CardTitle>المشاريع</CardTitle></CardHeader><CardContent className="space-y-3">{data.projects?.length ? data.projects.map((project: any) => <article key={project.id} className="rounded-2xl border border-[#ece2c9] p-4"><h3 className="font-bold">{project.name}</h3><p className="mt-2 line-clamp-2 text-sm leading-6 text-[#68747d]">{project.description}</p></article>) : <Empty icon={FolderKanban} text="ابدأ بإنشاء مشروعك الأول." />}</CardContent></Card><Card className="surface-card"><CardHeader><CardTitle>دورات الاختبار</CardTitle></CardHeader><CardContent className="space-y-3">{data.cycles?.length ? data.cycles.map((cycle: any) => <article key={cycle.id} className="flex items-center justify-between rounded-2xl border border-[#ece2c9] p-4"><div><p className="font-semibold">{cycle.title}</p><p className="mt-1 text-xs text-[#718089]">حتى {formatDate(cycle.endAt)}</p></div><StatusBadge status={cycle.status} /></article>) : <Empty icon={TestTube2} text="لم تنشئ أي دورة اختبار بعد." />}</CardContent></Card></section></div>;
}

function ClientAcceptedReportsSection({ reports }: { reports: any[] }) { return <div className="space-y-6"><section className="workspace-hero"><div><p className="eyebrow">التقارير المقبولة</p><h2>نتائج جاهزة للأعمال.</h2><p>تظهر هنا تقارير دوراتك المقبولة فقط مع أدلتها الخاصة.</p></div></section><Card className="surface-card"><CardContent className="space-y-3 pt-6">{reports.length ? reports.map((report) => <ReportRecord key={report.id} report={report} showFull />) : <Empty icon={CheckCircle2} text="لا توجد تقارير مقبولة بعد." />}</CardContent></Card></div>; }

function ClientParticipantsSection({ cycles }: { cycles: any[] }) { return <div className="space-y-6"><section className="workspace-hero"><div><p className="eyebrow">المتقدمون والدعوات</p><h2>اختر المشاركين في الدورة.</h2><p>أرسل الدعوات ببريد المختبر وراجع طلبات الانضمام من هنا.</p></div></section><section className="grid gap-6 xl:grid-cols-2"><InvitationPanel cycles={cycles} /><ApplicationPanel cycles={cycles} owner /></section></div>; }

function CommunityManagerWorkspaceV2({ data, section }: { data: any; section: string }) {
  if (section === "ttl-assignments") return <CommunityTtlAssignmentsSection data={data} />;
  if (section === "payouts") return <CommunityPayoutsSection data={data} />;
  return <div className="space-y-7"><section className="workspace-hero"><div><p className="eyebrow">نظرة مدير المجتمع</p><h2>إدارة موجزة، وعمليات في قوائمها.</h2><p>استخدم القائمة لإسناد قادة الاختبار أو تأكيد التحويلات ومراجعة سجل المعاملات.</p></div><Badge className="bg-[#f5e7ba] text-[#72521a]">صلاحية خاضعة للخادم</Badge></section><div className="grid gap-4 md:grid-cols-2"><Metric label="طلبات التحويل المعلقة" value={String(data.pendingPayouts?.length ?? 0)} note="تظهر ضمن التحويلات" icon={Banknote} /><Metric label="معاملات المختبرين" value={String(data.transactionsHistory?.length ?? 0)} note="تظهر ضمن التحويلات" icon={CircleDollarSign} /></div></div>;
}

function CommunityTtlAssignmentsSection({ data }: { data: any }) { const utils = trpc.useUtils(); const [cycleId, setCycleId] = useState(""); const [testerId, setTesterId] = useState(""); const testers = trpc.communityManager.eligibleTesters.useQuery(); const ttls = trpc.communityManager.cycleTtls.useQuery({ testCycleId: cycleId }, { enabled: Boolean(cycleId) }); const assign = trpc.communityManager.assignTtl.useMutation({ onSuccess: () => { toast.success("تم تحديث تعيين قائد فريق الاختبار."); ttls.refetch(); utils.workspace.dashboard.invalidate(); }, onError: (error) => toast.error(error.message) }); return <div className="space-y-6"><section className="workspace-hero"><div><p className="eyebrow">قادة الاختبار</p><h2>إسناد TTL بحسب الدورة.</h2><p>تظهر التعيينات الفعالة فقط وتُحسم الصلاحية من الخادم.</p></div></section><section className="grid gap-6 xl:grid-cols-2"><Card className="surface-card"><CardHeader><CardTitle>تعيين TTL</CardTitle></CardHeader><CardContent className="space-y-3"><select className="rtl-select" value={cycleId} onChange={(event) => setCycleId(event.target.value)}><option value="">اختر دورة اختبار</option>{(data.cycles ?? []).map((cycle: any) => <option key={cycle.id} value={cycle.id}>{cycle.title} · {cycle.projectName}</option>)}</select><select className="rtl-select" value={testerId} onChange={(event) => setTesterId(event.target.value)}><option value="">اختر مختبراً مكتمل الملف</option>{testers.data?.map((tester) => <option key={tester.id} value={tester.id}>{tester.name || tester.email || "حساب مختبر"} · سمعة {tester.reputationScore ?? 0}</option>)}</select><Button disabled={!cycleId || !testerId || assign.isPending} className="w-full bg-[#102a43]" onClick={() => assign.mutate({ testCycleId: cycleId, testerId, assign: true })}>تعيين قائد فريق الاختبار</Button></CardContent></Card><Card className="surface-card"><CardHeader><CardTitle>القادة الحاليون</CardTitle></CardHeader><CardContent className="space-y-3">{!cycleId ? <Empty icon={UsersRound} text="اختر دورة لعرض القادة المعينين." /> : ttls.data?.length ? ttls.data.map((ttl) => <article key={ttl.id} className="flex items-center justify-between gap-3 rounded-2xl border border-[#ece2c9] p-3"><div><p className="font-semibold">{ttl.testerName || ttl.testerEmail || "حساب مختبر"}</p><p className="text-xs text-[#77838c]">سمعة: {ttl.reputationScore ?? 0}</p></div><Button size="sm" variant="outline" disabled={assign.isPending} className="border-[#d59a83] text-[#aa4f37]" onClick={() => assign.mutate({ testCycleId: cycleId, testerId: ttl.testerId, assign: false })}>إزالة</Button></article>) : <Empty icon={UsersRound} text="لم يُعيّن قائد اختبار لهذه الدورة بعد." />}</CardContent></Card></section></div>; }

function CommunityPayoutsSection({ data }: { data: any }) { return <div className="space-y-6"><section className="workspace-hero"><div><p className="eyebrow">التحويلات والمعاملات</p><h2>تأكيد مرئي وسجل قابل للمراجعة.</h2><p>كل طلب جديد معلّق حتى يؤكد مدير المجتمع الإرسال، ثم يظهر حدث التحويل في السجل.</p></div></section><section className="grid gap-6 xl:grid-cols-2"><Card className="surface-card"><CardHeader><CardTitle>تأكيد إرسال التحويل</CardTitle></CardHeader><CardContent className="space-y-3">{data.pendingPayouts?.length ? data.pendingPayouts.map((item: any) => <CommunityPayoutReview key={item.id} request={item} />) : <Empty icon={Banknote} text="لا توجد طلبات سحب معلقة." />}</CardContent></Card><Card className="surface-card"><CardHeader><CardTitle>سجل كل المختبرين</CardTitle></CardHeader><CardContent className="space-y-3">{data.transactionsHistory?.length ? data.transactionsHistory.map((item: any) => <article key={item.id} className="rounded-2xl border border-[#ece2c9] p-3"><div className="flex items-center justify-between gap-3"><p className="font-semibold">{item.testerName || item.testerEmail || "حساب مختبر"}</p><span className={Number(item.amount) < 0 ? "text-[#a14a39]" : "text-[#1d6b4e]"}>{Number(item.amount) === 0 ? "—" : `${money(Math.abs(Number(item.amount)))} EGP`}</span></div><p className="mt-1 text-xs text-[#718089]">{transactionLabel(item.type)} · {item.note || "بدون ملاحظة"} · {formatDate(item.createdAt)}</p></article>) : <Empty icon={CircleDollarSign} text="لا توجد معاملات مسجلة بعد." />}</CardContent></Card></section></div>; }

export { ClientWorkspace, ClientWorkspaceV2, CommunityManagerWorkspaceV2, TesterReportsView, TtlReviewCard };
